274	// Main API catch-all -- routes through cached route definitions
275	//
276	// We use a single wildcard handler for /api/* rather than registering one
277	// Hono route per server route definition. This avoids blowing Hono's internal
278	// route trie limit and is simpler to reason about.
279	//
280	// Routing is done manually: iterate the route definitions, match method and
281	// path pattern, and delegate to the handler.
282	// ---------------------------------------------------------------------------
283	
284	// Simple Express-path to RegExp converter that handles `:param` segments.
285	function pathToRegex(path: string): { re: RegExp; paramNames: string[] } {
286	  const paramNames: string[] = [];
287	  const pattern = path
288	    .replace(/[$()*+.?[\\\]^{|}]/g, "\\$&") // escape regex metacharacters except :
289	    .replace(/:([a-zA-Z_][a-zA-Z0-9_]*)/g, (_match, name: string) => {
290	      paramNames.push(name);
291	      return "([^/]+)";
292	    });
293	  return { re: new RegExp(`^${pattern}$`), paramNames };
294	}
295	
296	// Pre-compile path matchers for each route at app startup.
297	// These are recomputed whenever the route cache is rebuilt.
298	let compiledRoutes: Array<{
299	  route: RouteDefinition;
300	  re: RegExp;
301	  paramNames: string[];
302	}> | null = null;
303	
304	function getCompiledRoutes(env: Env) {
305	  const cache = getRouteCache(env);
306	  if (!compiledRoutes) {
307	    compiledRoutes = cache.routes.map((route) => ({
308	      route,
309	      ...pathToRegex(route.path),
310	    }));
311	  }
312	  return { compiled: compiledRoutes, db: cache.db, storage: cache.storage };
313	}
